                const dep = entry.value_ptr;
                _ = new_group.putAssumeCapacityContext(builder.append(String, dep_name.slice(old_lockfile.buffers.string_bytes.items)), try dep.clone(pm, old_lockfile.buffers.string_bytes.items, @TypeOf(builder), builder), String.arrayHashContext(new_lockfile, null));
            }
